// Captured from pinned MathJax wrappers, not computed from native styles.
// Nested fraction scaling only: glyphs, general scripts and pixels remain open.
func TestMathJaxNestedFractionScale(t *testing.T) {
	for _, tc := range nestedFractionOracle {
		t.Run(tc.name, func(t *testing.T) {
			nodes, err := parser.Parse(tc.tex)
			if err != nil {
				t.Fatal(err)
			}
			o := layout.DefaultOptions()
			if !tc.display {
				o.Style = mathstyle.Text
			}
			o.FractionRulePadding = .1
			o.FractionScriptScale = 1 / math.Sqrt(2)
			o.MathJaxFractionMetrics = true
			var got [][3]float64
			var visit func(*layout.Box, float64)
			visit = func(b *layout.Box, scale float64) {
				switch c := b.Content.(type) {
				case layout.Fraction:
					got = append(got, [3]float64{scale, c.NumerScale, c.DenomScale})
					visit(c.Numer, scale*c.NumerScale)
					visit(c.Denom, scale*c.DenomScale)
				case layout.HBox:
					for _, child := range c.Children {
						visit(child, scale)
					}
				}
			}
			visit(layout.Layout(nodes, o), 1)
			if len(got) != len(tc.want) {
				t.Fatalf("fraction count %d want %d", len(got), len(tc.want))
			}
			for i := range got {
				if got[i] != tc.want[i] {
					t.Fatalf("fraction %d scale/children %v want %v", i, got[i], tc.want[i])
				}
			}
		})
	}
}

